contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 mintAmount, uint256 burnAmount) public {
        require(mintAmount < type(uint256).max - type(uint256).max / 4);
        require(burnAmount > mintAmount);
        c.mintToken(address(this), mintAmount); if (__ESBMC_reverted()) return;
        c.freezeAccount(address(this), true); if (__ESBMC_reverted()) return;
        bool burnReverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { burnReverted = true; } else { burnReverted = false; }
        assert(burnReverted && c.balanceOf(address(this)) == mintAmount && c.totalSupply() == mintAmount);
    }
    receive() external payable {}
}

