pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 mintAmount, uint256 burnAmount) internal {
        vm.assume(mintAmount < type(uint256).max - type(uint256).max / 4);
        vm.assume(burnAmount > mintAmount);
        try c.mintToken(address(this), mintAmount) {} catch { return; }
        try c.freezeAccount(address(this), true) {} catch { return; }
        bool burnReverted;
        try c.burn(burnAmount) { burnReverted = false; } catch { burnReverted = true; }
        assertTrue(burnReverted && c.balanceOf(address(this)) == mintAmount && c.totalSupply() == mintAmount);
    }

    function testFuzz_run(uint256 mintAmount, uint256 burnAmount) public {
        _run(mintAmount, burnAmount);
    }

    receive() external payable {}
}
